import{bV as i,aL as a,u as e,G as t}from"./chunks/framework.BfzMay2U.js";const p=JSON.parse('{"title":"如何留下好映像","description":"","frontmatter":{"title":"如何留下好映像","date":"2026-09-19T23:38:01.000Z"},"headers":[],"relativePath":"java/interview.md","filePath":"java/interview.md"}'),r={name:"java/interview.md"};function o(u,l,n,s,h,d){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="如何留下好映像" tabindex="-1">如何留下好映像 <a class="header-anchor" href="#如何留下好映像" aria-label="Permalink to &quot;如何留下好映像&quot;">​</a></h1><ul><li>确保不会流行坏映像</li><li>注意面试礼仪</li><li>让面试官感觉到你和其他候选人的区别</li></ul><h2 id="面试礼仪" tabindex="-1">面试礼仪 <a class="header-anchor" href="#面试礼仪" aria-label="Permalink to &quot;面试礼仪&quot;">​</a></h2><ul><li>守时，预留半小时，如果无法避免，提前沟通</li><li>见面问好，离开道谢</li><li>多用礼貌用语：请，谢谢</li><li>主动破冰，自我介绍要有亮点</li><li>避免刻意讨好的拍马屁</li><li>不要过分展示自己，过于夸大</li></ul><h2 id="事实和观点的区别" tabindex="-1">事实和观点的区别 <a class="header-anchor" href="#事实和观点的区别" aria-label="Permalink to &quot;事实和观点的区别&quot;">​</a></h2><blockquote><p>当时我遇到了一个技术难题，xxx (描述具体遇到的问题)，当时小组有 2 位同事先后尝试去解决这个问题，花了一段时间没有明显的进展。然后我主动去了解了这个问题，查看了相关源码，定位到了具体的问题，发现是 xxx 原因导致的，然后对这个问题进行了修复。</p></blockquote><p>当时项目遇到了一个技术难题，xxx，当时团队里没人能搞定这个问题，最终是我定位到问题并修复的。【夸大】</p><h2 id="体现你的不同" tabindex="-1">体现你的不同 <a class="header-anchor" href="#体现你的不同" aria-label="Permalink to &quot;体现你的不同&quot;">​</a></h2><ul><li>精心准备面试</li><li>突出自己的特点【技术上、项目上，解决了某个难度的问题，或者开源项目】，面试前深入的准备</li><li>表达对细分行业或者企业的喜欢</li></ul><blockquote><p>了解到贵公司是做 xxx 的，我对这方面很感兴趣，希望有机会在这个行业发展</p></blockquote><p>【需要提前了解这个行业的知识，面试官可能会让你谈谈企业的文化或价值观】</p><h2 id="冰山模型" tabindex="-1">冰山模型 <a class="header-anchor" href="#冰山模型" aria-label="Permalink to &quot;冰山模型&quot;">​</a></h2><h3 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p><img src="https://virusoss.oss-cn-shanghai.aliyuncs.com/image-20260919234922106.png" alt="image-20260919234922106" loading="lazy"></p><p>冰山以上的素质</p><ul><li>知识</li><li>技能</li></ul><p>冰山以下的素质</p><ul><li>价值观，两难问题的立场来判断</li><li>社会角色，自我形象和自我认知</li><li>个性，个人的思维方式，做事的风格，性格，适应能力</li><li>动机，个人对特定领域的想法</li></ul><p>面试的阶段考察的素质不同</p><ul><li>一面主要考察候选人能不能干活，也就是对知识和技能的考察</li><li>二面主要考察的是候选人是不是可培养，着重考察候选人的潜力</li><li>三面主要考察候选人的价值观，看候选人能干多久</li></ul><h3 id="对于求职者的意义" tabindex="-1">对于求职者的意义 <a class="header-anchor" href="#对于求职者的意义" aria-label="Permalink to &quot;对于求职者的意义&quot;">​</a></h3><ul><li>明确非技术类问题的出题方向和意图</li><li>重视冰山以下的部分的能力展示</li></ul><h3 id="如何应对冰山以下的问题" tabindex="-1">如何应对冰山以下的问题 <a class="header-anchor" href="#如何应对冰山以下的问题" aria-label="Permalink to &quot;如何应对冰山以下的问题&quot;">​</a></h3><ul><li>价值观方面：组织利益要优先于个人利益；长期利益要优先于短期利益，在不影响企业需求的情况下兼容个人需求</li><li>自我形象和认知层面：需要表现出愿意学习，愿意探索未知的领域，把失败当做经历而非结果。</li><li>个性方面：表现出自己的适应能力，能调整自己的风格，更快的适应团队</li><li>动机方面：尽可能表现出对企业和业务的兴趣和对技术的追求</li></ul><h2 id="面试秘笈" tabindex="-1">面试秘笈 <a class="header-anchor" href="#面试秘笈" aria-label="Permalink to &quot;面试秘笈&quot;">​</a></h2><ul><li>面试前：投入最多精力的地方，主动去总结 <ul><li>精心制作简历，并选择合适的投递渠道 <ul><li>各大招聘网站 ，拉钩，boss 直聘</li><li>公司网站</li><li>线下招聘会</li><li>社交平台，公司的微博或公众号</li><li>猎头【说明企业对人才的需求较大】</li><li>内推 <strong>优先考虑内推</strong></li></ul></li><li><strong>参加面试前，详细了解企业的情况</strong><ul><li>企业基本信息，所属的行业，发展前景，行业中的位置</li><li>创始人的背景</li><li>企业的核心产品，盈利情况</li><li>企业的价值观使命和愿景</li><li>你面试的部门对企业的价值或者企业里的地位</li><li>企业认为我的哪些方面比较适合这个岗位</li><li>项目组人数，主要业务，技术栈，团队技术氛围咋样</li><li>直接汇报的对象的岗位</li></ul></li><li>做好充分的面试准备 <ul><li>面试开始前的准备 <ul><li>着装得体</li><li>保持微笑和良好的心理状态</li><li>充分休息，带上打印好的简历</li></ul></li><li>技术面试的准备，投入最多精力的 <ul><li>简历上出现的知识点一定要准备扎实，进行系统的梳理</li><li>准备好项目相关的面试问题和答案</li><li>算法面试</li><li>介绍你最近/最有成就感/最困难的项目</li><li>介绍下你处理过的最难的技术问题</li><li>介绍一个你犯过的技术问题或者造成的故障</li><li>根据 star 提问法，针对每个项目提问以及答案</li><li>展示自己在项目中的重要性 <ul><li>针对复杂需求设计了什么方案，难点是什么？怎么解决的 ？</li><li>项目最终达到什么样的成果？自己发挥着什么样的角色？</li><li>项目完成后你总结了什么经验？有哪些不足？有什么改进方案？</li><li>养成整理和记录的习惯</li><li>找那些能让自己简历有亮点的工作</li></ul></li></ul></li><li>非技术面试的准备 <ul><li>根据岗位要求准备自我介绍【面试的第一阶段】 <ul><li>精心准备、按需调整、表现<strong>匹配度</strong>和<strong>亮点</strong></li><li>表达对行业，企业，业务或技术的兴趣</li><li>自我介绍控制在 2 到 3 分钟，简历上有的东西要简化或一笔带过</li></ul></li><li>提前准备冰山以下部分的面试题</li></ul></li></ul></li><li>多进行模拟面试 <ul><li>多面试找状态</li><li>多面试找不足</li><li>可以自己找朋友充当面试官，或者找镜子</li></ul></li><li>注意行为细节，避免扣印象分，紧张的时候会有小动作</li><li>注意沟通效率，结果先行</li><li>向面试官提问要恰当 <ul><li>询问一些关于团队或项目，以及网上获取不到的信息</li></ul></li></ul></li><li>面试中 <ul><li>避免挤牙膏式的问题</li><li>需要自己要问什么，以及问什么合适</li></ul></li><li>面试后 <ul><li>总结和复习</li><li>对没回答出来的面试题进行补救</li></ul></li></ul>',26)])])}const b=i(r,[["render",o]]);export{p as __pageData,b as default};
